float fa(vec2 P,vec4 r){ vec2 c=vec2((r.x+r.z)*.5,r.w); float rx=(r.z-r.x)*.5, ry=r.w-r.y; float e=(length((P-c)/vec2(rx,ry))-1.)*min(rx,ry); return max(e,P.y-r.w); }
