  float upper=step(600.,P.y)*step(P.y,985.)*(1.-z.x)*(1.-z.y); float lower=step(985.,P.y)*(1.-z.x)*(1.-z.y);
  float wA=z.y+merge*.2; float wW=z.x+merge*.2; float wT=upper+merge*.2; float wM=lower+merge*.2;
