  vec2 fq=q*3.+vec2(cam.x*2.,t*.5); vec2 fid=floor(fq); vec2 fo=vec2(hash(fid)-.5,hash(fid+7.)-.5)*.5; float fl=smoothstep(.12,0.,length(fract(fq)-.5-fo*sin(t+hash(fid)*6.)));
